//! Provenance ledger: every calculation step the engine performs, with the game evidence behind it.
//!
//! PROVEN = traced in the compiled game code (function address, decompile in `analysis/`) or read directly from a
//! game data field. INFERRED = follows from code or data but not traced end to end. ASSUMED = no game evidence
//! (player behaviour, scenario choice or placeholder). `ens proof` writes this table to docs/research/provenance.md.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Proven,
    Inferred,
    Assumed,
    /// A situation you choose in the planner (group size, fight length, item level…), not a game rule.
    Scenario,
}

impl Status {
    pub fn label(self) -> &'static str {
        match self {
            Status::Proven => "PROVEN",
            Status::Inferred => "INFERRED",
            Status::Assumed => "ASSUMED",
            Status::Scenario => "SCENARIO",
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Proof {
    pub id: &'static str,
    pub area: &'static str,
    pub step: &'static str,
    pub status: Status,
    pub evidence: &'static str,
    /// What would move it to PROVEN (empty when proven).
    pub open: &'static str,
}

use Status::*;

