/// Game systems the planner does not calculate yet (listed in the proof file so nothing is silently missing).
/// Rules (by proof id) that in-game combat logs have checked: the log files and the game build they were recorded on.
/// Golden vectors in review/golden_vectors.csv are the stronger check; these are the recorder's logs.
pub const MEASURED: &[(&str, &str)] = &[
    ("summon.rate", "combat-1792717052.csv, combat-1792718413.csv (game build 1273043): 2.4 and 2.6 s between a Hollow Wretch's swings"),
    ("summon.damage", "combat-1792717052.csv (game build 1273043): a level-19 character's Hollow Wretch I hits at level 17, the spell's level"),
];

/// The game build whose executable the exe addresses in the evidence come from (the analysed copy, target/enshrouded.exe
/// and analysis/). The data is newer (bundle meta.kfcVersion); hotfix 1.0.0.3's notes list no combat changes, but the
/// addresses have not been re-read in that build.
pub const EXE_BUILD: &str = "1269579 (hotfix 1.0.0.2)";

/// Whether a rule's evidence cites addresses in the game's executable.
pub fn cites_exe(p: &Proof) -> bool {
    p.evidence.contains("0x14") || p.evidence.contains("exe ")
}

/// Where an in-game log has checked this rule, if one has.
pub fn measured(id: &str) -> Option<&'static str> {
    MEASURED.iter().find(|(i, _)| *i == id).map(|x| x.1)
}

pub const NOT_MODELED: &[(&str, &str)] = &[
    ("Zone spell debuffs", "Zone spells (Pillar Of Flames, Blizzard) apply a debuff (burn, slow) to every enemy they hit; it is not priced."),
    ("Wand heavy attacks", "1.0 gave wands a heavy attack: a piercing projectile at twice the normal shot's damage over a 1.97 s animation that passes through every enemy in its line. The planner prices only the wand's normal shot."),
    ("Summon scrolls", "Consumables that summon a damage dealer (such as Fire Wisp Summon) are not in the summon list or the numbers."),
    ("Rune perk unlock cost", "Unlocking an item's perks costs runes (Legendary Runes for legendary items). The planner assumes every available perk is unlocked and does not count the rune cost."),
    ("Skills that depend on how you play", "Parry, overpower, when-hit, healing-allies, stun, aggro and sneaking skills are listed under Coverage as \"depends on how you play\": they change nothing in the planner's numbers unless that situation happens."),
];

pub fn get(id: &str) -> Option<&'static Proof> {
    PROOFS.iter().find(|p| p.id == id)
}

/// The ledger as Markdown.
pub fn markdown() -> String {
    let mut s = String::from("# Calculation proof\n\nEvery calculation step Unshrouded performs, and the game evidence behind it.\n\n- **PROVEN**: traced in the game's compiled code (function address; decompiles in `analysis/`) or read directly from a field in the game's data files.\n- **INFERRED**: follows from game code or data, but not traced end to end yet.\n- **ASSUMED**: no game evidence yet (a placeholder).
- **SCENARIO**: a situation you choose in the planner (group size, fight length, the item level you set…); the game rules around it are proven or listed separately.\n\nGenerated by `ens proof` from `planner/crates/ens-calc/src/proof.rs`. Anything not PROVEN is being worked on.\n\n");
    s += &format!("Exe addresses in the evidence were read in build {EXE_BUILD}.\n\n");
    let n = |st: Status| PROOFS.iter().filter(|p| p.status == st).count();
    s += &format!("{} proven · {} inferred · {} assumed · {} scenario\n", n(Proven), n(Inferred), n(Assumed), n(Scenario));
    let mut area = "";
    for p in PROOFS {
        if p.area != area {
            area = p.area;
            s += &format!("\n## {area}\n\n| Step | Status | Evidence | Still needed |\n|---|---|---|---|\n");
        }
        s += &format!("| {} | {} | {} | {} |\n", p.step.replace('|', "/"), p.status.label(), p.evidence.replace('|', "/"), p.open.replace('|', "/"));
    }
    s += "\n## Not calculated yet\n\nThese game systems exist in the game files but the planner does not include them in its numbers yet.\n\n";
    for (name, what) in NOT_MODELED {
        s += &format!("- **{name}**: {what}\n");
    }
    s
}

#[cfg(test)]
mod tests {
    #[test]
    fn ids_unique_and_referenced_ids_exist() {
        let mut ids: Vec<&str> = super::PROOFS.iter().map(|p| p.id).collect();
        ids.sort();
        let n = ids.len();
        ids.dedup();
        assert_eq!(n, ids.len(), "duplicate proof id");
        // every proof("…") reference in the engine sources must name a ledger entry
        for src in [include_str!("lib.rs"), include_str!("build.rs")] {
            for part in src.split("proof(\"").skip(1) {
                let id = part.split('"').next().unwrap();
                assert!(super::get(id).is_some(), "unknown proof id {id}");
            }
        }
    }
}
